import 'package:flutter/material.dart';
void main()=>runApp(const Nova());
enum Role{customer,restaurant,courier,admin}
class Product{final String name,store,emoji;final double price;const Product(this.name,this.store,this.emoji,this.price);}
const products=[Product('برجر كلاسيك','برجر هاوس','🍔',120),Product('فراخ كرسبي','تشيكن تايم','🍗',145),Product('بيتزا مارجريتا','بيتزا بلس','🍕',180),Product('شاورما عربي','شاورما ستار','🌯',95),Product('باستا ألفريدو','إيطاليانو','🍝',160)];
class Nova extends StatelessWidget{const Nova({super.key});Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Nova Delivery • UI Preview',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xffff5a36))),home:const App());}
class App extends StatefulWidget{const App({super.key});State<App> createState()=>_App();}
class _App extends State<App>{Role role=Role.customer;int tab=0;final cart=<Product,int>{};void add(Product p)=>setState(()=>cart[p]=(cart[p]??0)+1);void sub(Product p)=>setState(()=>cart[p]==1?cart.remove(p):cart[p]=cart[p]! - 1);double get total=>cart.entries.fold(0,(s,e)=>s+e.key.price*e.value);
Widget build(BuildContext c){if(role!=Role.customer)return Panel(role:role,onRole:(r)=>setState(()=>role=r));final pages=[Home(add:add),Search(add:add),const Orders(),Cart(cart:cart,total:total,add:add,sub:sub),Profile(onRole:(r)=>setState(()=>role=r))];return Scaffold(appBar:AppBar(title:const Text('Nova Delivery',style:TextStyle(fontWeight:FontWeight.bold)),actions:[IconButton(onPressed:()=>setState(()=>tab=3),icon:Badge(isLabelVisible:cart.isNotEmpty,label:Text(cart.length.toString()),child:const Icon(Icons.shopping_bag_outlined))),IconButton(onPressed:()=>notify(c),icon:const Icon(Icons.notifications_none))]),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.search),label:'بحث'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'طلباتي'),NavigationDestination(icon:Icon(Icons.shopping_bag),label:'السلة'),NavigationDestination(icon:Icon(Icons.person),label:'حسابي')]);}}
class Home extends StatelessWidget{final void Function(Product) add;const Home({super.key,required this.add});Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xffff5a36),Color(0xffff8a65)]),borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('جوعان؟ 😋',style:TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.bold)),SizedBox(height:8),Text('أكلك المفضل لحد باب البيت',style:TextStyle(color:Colors.white)),SizedBox(height:16),TextField(decoration:InputDecoration(hintText:'ابحث عن مطعم أو وجبة...',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderSide:BorderSide.none)))])),const SizedBox(height:20),const Text('التصنيفات',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold)),SizedBox(height:90,child:ListView(scrollDirection:Axis.horizontal,children:['🍔 برجر','🍕 بيتزا','🍗 فراخ','🌯 شاورما','🍝 باستا','🥗 صحي'].map((x)=>SizedBox(width:90,child:Card(child:Center(child:Text(x,textAlign:TextAlign.center))))).toList())),const SizedBox(height:18),const Text('الأكثر طلباً',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold)),...products.map((p)=>Card(child:ListTile(leading:Text(p.emoji,style:const TextStyle(fontSize:32)),title:Text(p.name,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(p.store+' • '+p.price.toStringAsFixed(0)+' ج.م'),trailing:IconButton.filled(onPressed:()=>add(p),icon:const Icon(Icons.add)))))]);}
class Search extends StatelessWidget{final void Function(Product) add;const Search({super.key,required this.add});Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const TextField(decoration:InputDecoration(prefixIcon:Icon(Icons.search),hintText:'ابحث...',border:OutlineInputBorder())),...products.map((p)=>Card(child:ListTile(leading:Text(p.emoji,style:const TextStyle(fontSize:28)),title:Text(p.name),subtitle:Text(p.store),trailing:IconButton.filled(onPressed:()=>add(p),icon:const Icon(Icons.add)))))]);}
class Orders extends StatelessWidget{const Orders({super.key});Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('طلباتي',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),order('NV-1028','قيد التوصيل','برجر هاوس'),order('NV-1021','تم التسليم','بيتزا بلس'),order('NV-1009','ملغي','شاورما ستار')]);Widget order(String id,String s,String st)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.receipt_long)),title:Text('#'+id),subtitle:Text(st+' • '+s),trailing:const Icon(Icons.chevron_left)));}
class Cart extends StatelessWidget{final Map<Product,int> cart;final double total;final void Function(Product) add,sub;const Cart({super.key,required this.cart,required this.total,required this.add,required this.sub});Widget build(BuildContext c)=>cart.isEmpty?const Center(child:Text('السلة فارغة',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))):Column(children:[Expanded(child:ListView(padding:const EdgeInsets.all(16),children:cart.entries.map((e)=>Card(child:ListTile(leading:Text(e.key.emoji,style:const TextStyle(fontSize:28)),title:Text(e.key.name),subtitle:Text(e.key.price.toStringAsFixed(0)+' ج.م'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>sub(e.key),icon:const Icon(Icons.remove)),Text(e.value.toString()),IconButton(onPressed:()=>add(e.key),icon:const Icon(Icons.add))])))).toList())),SafeArea(child:Padding(padding:const EdgeInsets.all(16),child:FilledButton(onPressed:()=>checkout(c,total),child:SizedBox(width:double.infinity,child:Center(child:Text('تأكيد الطلب • '+total.toStringAsFixed(0)+' ج.م'))))))]);}
class Profile extends StatelessWidget{final void Function(Role) onRole;const Profile({super.key,required this.onRole});Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const CircleAvatar(radius:45,child:Icon(Icons.person,size:45)),const SizedBox(height:12),const Center(child:Text('حساب العميل',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))),...['بيانات الحساب','العناوين','طرق الدفع','الكوبونات','المفضلة','الإشعارات','الإعدادات','الدعم'].map((x)=>Card(child:ListTile(title:Text(x),trailing:const Icon(Icons.chevron_left)))),const Text('لوحات النظام',style:TextStyle(fontWeight:FontWeight.bold)),Wrap(spacing:8,children:[ActionChip(label:const Text('مطعم'),onPressed:()=>onRole(Role.restaurant)),ActionChip(label:const Text('مندوب'),onPressed:()=>onRole(Role.courier)),ActionChip(label:const Text('مالك/إدارة'),onPressed:()=>onRole(Role.admin))])]);}
class Panel extends StatelessWidget{final Role role;final void Function(Role) onRole;const Panel({super.key,required this.role,required this.onRole});Widget build(BuildContext c){final admin=role==Role.admin,rest=role==Role.restaurant;final title=admin?'لوحة المالك والإدارة':rest?'لوحة المطعم':'لوحة المندوب';final sections=admin?['إدارة الطلبات','العملاء','المطاعم','المندوبون','المدفوعات','المحفظة','الكوبونات والعروض','التقارير والتحليلات','الإشعارات','الشكاوى','الأدوار والصلاحيات','إعدادات المنصة']:rest?['الطلبات','قائمة الطعام والأسعار','المخزون','ساعات العمل','العروض','المبيعات والتقارير','التقييمات','إعدادات المطعم']:['الطلبات المتاحة','الطلبات الحالية','الخريطة والتوجيه','الأرباح والمحفظة','سجل التوصيلات','التقييمات','بيانات المركبة','الدعم'];return Scaffold(appBar:AppBar(title:Text(title),actions:[PopupMenuButton<Role>(onSelected:onRole,itemBuilder:(_)=>const[PopupMenuItem(value:Role.customer,child:Text('العميل')),PopupMenuItem(value:Role.restaurant,child:Text('المطعم')),PopupMenuItem(value:Role.courier,child:Text('المندوب')),PopupMenuItem(value:Role.admin,child:Text('الإدارة'))])]),body:ListView(padding:const EdgeInsets.all(16),children:[GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,children:['الطلبات|286','المبيعات|48,620 ج.م','المطاعم|124','المندوبون|87'].map((x){final p=x.split('|');return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.analytics),const Spacer(),Text(p[0]),Text(p[1],style:const TextStyle(fontSize:19,fontWeight:FontWeight.bold))])));}).toList()),...sections.map((x)=>Card(child:ListTile(title:Text(x),leading:const Icon(Icons.settings_outlined),trailing:const Icon(Icons.chevron_left),onTap:()=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('فتح: '+x))))))]));}}
void notify(BuildContext c)=>showModalBottomSheet(context:c,builder:(_)=>const SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(title:Text('الإشعارات',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))),ListTile(leading:Icon(Icons.local_offer),title:Text('خصم 20% على طلبك القادم')),ListTile(leading:Icon(Icons.delivery_dining),title:Text('المندوب في الطريق'))])));
void checkout(BuildContext c,double total)=>showModalBottomSheet(context:c,builder:(_)=>Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('تأكيد الطلب',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const ListTile(leading:Icon(Icons.location_on),title:Text('عنوان التوصيل'),subtitle:Text('المنزل')),const ListTile(leading:Icon(Icons.payments),title:Text('الدفع'),subtitle:Text('الدفع عند الاستلام')),Text('الإجمالي: '+total.toStringAsFixed(0)+' ج.م'),FilledButton(onPressed:(){Navigator.pop(c);ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('تم إنشاء الطلب بنجاح 🎉')));},child:const Text('تأكيد'))])));